text:
  const key = digest([record.kind, record.component || "", [...record.paths].sort(), record.text.trim().toLowerCase()]);
  if (seen.has(key)) continue;
  let source = record.source;
  const sourceExcerpt = JSON.stringify(source).length > 1600;
  if (sourceExcerpt) {
    source = Object.fromEntries(["type", "revision", "file", "reference", "url", "verified", "accepted", "reverted", "sourceAt", "basis", "verification"]
      .filter(key => source[key] !== undefined && JSON.stringify(source[key]).length <= 900).map(key => [key, source[key]]));
  }
  const entry = JSON.stringify({ id: record.id, kind: record.kind, status: record.status || "observation", at: record.at,
    title: record.title, paths: record.paths, source, sourceExcerpt, retrievalReason: record.retrievalReason,
    text: record.match ? `${record.match.context}\n${record.match.text}` : excerptFor(record.text, words, record.kind === "lesson" ? 2400 : 1400),
    section: record.match && store.get(record.match.recordId).text.length > 1200 ? { id: record.match.id, recordId: record.match.recordId, start: record.match.start, end: record.match.end, headings: record.match.headings, metadata: record.match.metadata, file: store.file(store.get(record.match.recordId)) } : undefined,
    excerpt: record.text.length > (record.kind === "lesson" ? 2400 : 1400),
    file: store.file(record), evidence: record.evidence,
    aliases: cached.aliases.get(record.id)?.slice(0, 8) });
  if (text.length + entry.length + 1 > maxChars) continue;
  text += entry + "\n";
  selected.push(record.id); seen.add(key);
  if (selected.length >= limit) break;
}
return { text: selected.length ? text : "", ids: selected, retrieval };
